import fs from 'node:fs';import {createRequire} from 'node:module';import {render,sample} from './clock-v6.mjs';
const require=createRequire(import.meta.url),sharp=require(process.env.CODEX_PRIMARY_RUNTIME_NODE_MODULES+'/sharp');
const renderDir=process.env.V6_RENDER_DIR||'/tmp/naotocchi-clock-v6-renders';fs.mkdirSync(renderDir,{recursive:true});
const art='data:image/png;base64,'+fs.readFileSync(new URL('../assets/dial-art-v4.png',import.meta.url)).toString('base64');
for(const v of ['v5','weak','medium','metalA','metalB','candidate','bezel1','bezel15','bezel2']){let s=render(sample,{variant:v,sameScale:true});s=s.replaceAll('../assets/dial-art-v4.png',art);await sharp(Buffer.from(s)).resize(1024,1024).png().toFile(`${renderDir}/${v}.png`);}
const coords={center:[.5,.25],left:[.12,.5],right:[.88,.5],top:[.4,.12],bottom:[.4,.87]};
const med=a=>a.sort((a,b)=>a-b)[Math.floor(a.length/2)];
async function sampleFile(file,clock=false){const {data,info}=await sharp(file).removeAlpha().raw().toBuffer({resolveWithObject:true});const result={};for(const [name,[x,y]]of Object.entries(coords)){const rgb=[[],[],[]];for(let dy=-12;dy<=12;dy++)for(let dx=-12;dx<=12;dx++){let i=(Math.round((clock?(24+y*1024)/1072:y)*info.height+dy)*info.width+Math.round((clock?(24+x*1024)/1072:x)*info.width+dx))*3;let p=[data[i],data[i+1],data[i+2]];if(p[2]-p[0]>18&&p[2]>p[1])p.forEach((v,k)=>rgb[k].push(v));}result[name]=rgb.map(med);}return result;}
const card=await sampleFile(new URL('../assets/official-card-back.png',import.meta.url).pathname),before=await sampleFile(`${renderDir}/v5.png`,true),after=await sampleFile(`${renderDir}/candidate.png`,true);
const dist=(a,b)=>Math.hypot(...a.map((v,i)=>v-b[i]));const rows=Object.keys(coords).map(name=>({name,normalizedPoint:coords[name],card:card[name],v5:before[name],v6:after[name],rgbDistanceV5:dist(card[name],before[name]),rgbDistanceV6:dist(card[name],after[name])}));const result={method:'25x25 patches at normalized coordinates; median of blue pixels B-R>18 and B>G; Euclidean sRGB distance (not perceptual Delta E). Different images have different composition; indicative material comparison only.',rows,meanV5:rows.reduce((a,r)=>a+r.rgbDistanceV5,0)/5,meanV6:rows.reduce((a,r)=>a+r.rgbDistanceV6,0)/5};fs.writeFileSync(new URL('evidence/color.json',import.meta.url),JSON.stringify(result,null,2));console.log(JSON.stringify(result,null,2));
